#!/bin/bash\n\necho \"Testing Registration Rate Limiting...\"\n\n# Send 10 registration requests quickly to test rate limiting\n# Rate limit is 5 per 10 minute window per IP, but in our test we set it to 5 per 10 seconds\nfor i in {1..7}; do\n  echo \"Request $i:\"\n  response=$(curl -s -X POST http://localhost:3000/api/register \\\n    -H \"Content-Type: application/json\" \\\n    -d '{\n      \"email\": \"ratetest'$i'@example.com\",\n      \"password\": \"password123\",\n      \"name\": \"Rate Test User\",\n      \"collegeName\": \"Test College\",\n      \"rollNumber\": \"12348\",\n      \"phone\": \"1234567893\"\n    }' 2>/dev/null)\n  \n  http_code=$(curl -s -o /dev/null -w \"%{http_code}\" -X POST http://localhost:3000/api/register \\\n    -H \"Content-Type: application/json\" \\\n    -d '{\n      \"email\": \"ratetester'$i'@example.com\",\n      \"password\": \"password123\",\n      \"name\": \"Rate Test User\",\n      \"collegeName\": \"Test College\",\n      \"rollNumber\": \"12348\",\n      \"phone\": \"1234567894\"\n    }')\n  \n  echo \"Status: $http_code, Response: $response\"\n  sleep 0.5\ndone